# -*- coding: utf-8 -*-
from fams import *
F = 'user'
REFUND = ('What if the username claim does not work?', 'If a username claim fails, you get a full 100% refund. A claim fails when the username is not successfully claimed onto your profile. Details are on the refund policy page.')
def u(slug, title, h1, crumb, desc, hero, answer, cards, secs, faq, who, **kw):
    page(slug, F, title, desc, h1, crumb, hero, answer, cards, secs, faq + [REFUND], who, **kw)
RULES = 'Every claim goes through the platform’s own processes. No bots, no false reports, no buying or selling accounts.'
u('instagram-username-lost-after-rebrand', 'Instagram Username Lost After a Rebrand',
 'Lost your Instagram username during a rebrand?', 'Username lost after a rebrand',
 'Changed your Instagram handle for a rebrand and someone else took the old one, or you want it back? What can be done and what to avoid.',
 'Releasing a handle during a rebrand can let someone else take it. Here is what to check.',
 'When you change your Instagram handle, the old one is released and others can register it. If a rebrand left you without your original name, check whether the new holder is active, whether it matches your trademark or business name, and which official route fits. Do not buy it from the holder.',
 [('Check who holds it', 'Active, empty or copying your brand each point to a different route.'),
  ('Use your brand papers', 'Registration or trademark details support a brand report.'),
  ('Do not pay the holder', 'Paying for a handle can put your own account at risk.')],
 [S('What may apply', ul(['An empty or inactive account on the handle may fit the inactive account route.', 'An account copying your brand may fit a brand or impersonation report.', 'A normal active account owned by someone else is hard to claim.', 'If the handle is available, you can simply change back.']),
    RULES),
  S('What to send', ol(['The old handle and your current handle.', 'What the old handle was used for and for how long.', 'Brand or business registration details, if any.', 'A screenshot of the handle’s current profile.']))],
 [('Can I just switch back?', 'Only if the handle is available. Check by trying to change to it.'),
  ('Does a trademark help?', 'It can support a brand report, depending on the facts.'),
  ('Will followers move to the old handle?', 'Followers stay on your profile. Only the name changes.')],
 ['Brands that renamed and regret it.', 'Creators who changed their handle for a campaign.', 'Founders whose first handle was released.'])

u('instagram-username-taken-by-fan-page', 'Instagram Username Taken by a Fan Page',
 'A fan page holds your Instagram username?', 'Username held by a fan page',
 'A fan account took your name or brand handle? How fan pages are treated, when a report applies and what a claim needs.',
 'Fan pages are common and not always breaking a rule. The route depends on how it presents itself.',
 'A fan page is allowed to exist, but not to pose as you or your brand. If it uses your exact name, photo or logo in a way that suggests it is official, an impersonation or brand report may apply. If it is clearly labelled as a fan page, a claim is harder and the route is different.',
 [('Read how it presents itself', 'Labelled fan page or posing as you?'),
  ('Collect proof', 'Your ID, brand papers, or official accounts that link to you.'),
  ('Do not message them aggressively', 'A friendly approach is not our call, but threats can backfire.')],
 [S('What decides the route', ul(['The bio says fan page, tribute or unofficial.', 'It posts as if it were you, uses your logo or sells in your name.', 'It has been inactive for a long time.', 'It uses a slightly different spelling of your name.']),
    RULES),
  S('What to send', ol(['The handle you want and the fan page handle.', 'Screenshots of the fan page bio and recent posts.', 'Proof you are the person or brand named.', 'Anything that shows it is posing as you.']))],
 [('Can a fan page keep my name?', 'If it is clearly labelled and not misleading, usually yes.'),
  ('Does verification help?', 'It helps show who is official, but it is not required for a report.'),
  ('Will the page be deleted?', 'Not necessarily. We cannot promise any outcome.')],
 ['Public figures and creators.', 'Brands with fan communities.', 'Musicians and artists.'])

u('instagram-username-taken-by-competitor', 'Instagram Username Taken by a Competitor',
 'A competitor holds the Instagram username you want?', 'Username held by a competitor',
 'A competing business holds your brand handle on Instagram? When a trademark or impersonation report applies and when it does not.',
 'Holding a similar name is not always illegal. The route depends on facts, not on the rivalry.',
 'If a competitor holds a handle matching your brand, the route depends on whether they confuse customers, use your trademark, or simply picked a similar name. A registered trademark and proof of earlier use strengthen a report. A generic name with no registration is harder. We tell you honestly which side your handle is on.',
 [('Check your trademark', 'Registered marks give stronger grounds.'),
  ('Show earlier use', 'Dated invoices, domains and posts show you were first.'),
  ('Look for confusion', 'Do they use your name to mislead customers?')],
 [S('What strengthens a claim', ul(['A registered trademark in the relevant country.', 'A domain, trading name or company registered earlier than theirs.', 'Evidence that customers are confused between the two accounts.', 'The competitor using your logo or product names.']),
    RULES),
  S('What to send', ol(['The handle you want, and the holder’s handle.', 'Trademark number or business registration.', 'Dated proof that your name came first.', 'Screenshots of their profile and any confusion.']))],
 [('Is it worth a trademark filing?', 'That is a legal question for a professional. A registered mark helps but is not required for every report.'),
  ('Will the competitor be told?', 'Reports are handled by the platform. We do not contact the holder.'),
  ('Can I just buy the handle?', 'Buying and selling accounts breaks the rules and puts your account at risk.')],
 ['Founders protecting a brand name.', 'Agencies acting for a business.', 'Shops that lost a handle to a similar brand.'])

u('instagram-username-claim-for-restaurants', 'Instagram Username Claim for Restaurants',
 'Want the Instagram username that matches your restaurant name?', 'Username claim for restaurants',
 'Restaurants that want the Instagram handle matching their name: when a claim can work, what proof helps and what stays with the current holder.',
 'Customers search by restaurant name. If a fan, a former owner or an inactive account holds it, here is what to check.',
 'A restaurant’s handle is often held by a former owner, a food blogger or an abandoned account. Check whether it is active, whether it uses your name or logo, and what proof you have: registered business name, signage, menus and a website. Those decide which official route fits. We will tell you plainly if the handle is not claimable.',
 [('Is it active?', 'Empty or abandoned accounts follow a different route from active ones.'),
  ('Show the business is yours', 'Registration, website, signage and menus.'),
  ('Check old owners', 'A former owner may still run it.')],
 [S('Common situations', ul(['An old account opened by a previous owner.', 'A food blogger who used the restaurant name in their handle.', 'A copy account posting your menu.', 'A handle with a slightly different spelling that the restaurant uses instead.']),
    RULES),
  S('What to send', ol(['The handle you want and your current restaurant account.', 'Registered business name and address, and your website.', 'A screenshot of the holder’s profile.', 'Why the name is yours: opening date, signage or listings.']))],
 [('Can a restaurant with a common name get its handle?', 'It depends. Generic names are harder.'),
  ('What about a former owner?', 'If they still run it, the route changes. Tell us the history.'),
  ('Will the menu photos move?', 'No. The handle goes onto your profile. Posts stay where they are.')],
 ['Independent restaurants.', 'New cafes and bars.', 'Restaurant groups.'])

u('instagram-username-claim-for-authors', 'Instagram Username Claim for Authors',
 'Want the Instagram username that matches your author name?', 'Username claim for authors',
 'Authors who want the Instagram handle matching their pen name or book title: when a claim fits, what proof helps and what to expect.',
 'Your name is on your books, but the handle might be held by someone else. Here is how it is assessed.',
 'Authors often find their name or pen name taken by a reader account, a namesake or an abandoned profile. A claim depends on whether the account is active, whether it poses as you, and what proof you hold: published books, a website, a publisher listing. Pen names and common names are harder, and we say so early.',
 [('Show your published work', 'Book listings, publisher page and website.'),
  ('Check for namesakes', 'A real person with the same name has equal claim.'),
  ('Use the pen name consistently', 'Same name across book, website and profile.')],
 [S('Situations we see', ul(['A reader or reviewer account using the author name.', 'A namesake who is not a writer.', 'An abandoned account with the pen name.', 'A copy account using your cover art.']),
    RULES),
  S('What to send', ol(['The handle you want and your current author account.', 'Links to your books, publisher page or website.', 'A screenshot of the holder’s profile.', 'Whether the name is a pen name, and how long you have used it.']))],
 [('What if there is another person with my name?', 'A real namesake who is active will usually keep their handle.'),
  ('Does a book title count?', 'It can support a claim, but titles are rarely protected on their own.'),
  ('Do I need a verified badge?', 'No. It is not required for a claim.')],
 ['Self-published and traditionally published authors.', 'Writers using a pen name.', 'Small publishers.'])

u('instagram-username-claim-for-musicians', 'Instagram Username Claim for Musicians',
 'Want the Instagram username that matches your artist name?', 'Username claim for musicians',
 'Musicians and bands who want the Instagram handle matching their artist name: when a claim can work and what proof supports it.',
 'Fans make accounts with your name before you do. Here is how a handle held by someone else is assessed.',
 'Artist names are often taken early by fans, fake accounts or unrelated people. The route depends on whether the account is active, whether it passes itself off as you, and what you can show: streaming profiles, release history, press and a website. A clearly labelled fan account is harder. We give you an honest read before anything is filed.',
 [('Show releases', 'Streaming profiles and release dates.'),
  ('Check for a copy account', 'A fan page is different from a fake.'),
  ('Keep the name consistent', 'Same name on every platform helps.')],
 [S('What we often see', ul(['A fan account using the artist name and your photos.', 'A namesake musician in another country.', 'An abandoned account made years ago.', 'A fake account used for ticket or merch scams.']),
    RULES),
  S('What to send', ol(['The handle you want and your current artist profile.', 'Links to streaming profiles and press.', 'Screenshots of the other profile.', 'How long you have used the name.']))],
 [('What if a fake is selling merch under my name?', 'Tell us. That is closer to an impersonation report, and the route is different.'),
  ('Do I need many followers?', 'No. Proof of the name is what matters, not follower count.'),
  ('What if two bands share a name?', 'Active namesakes usually keep their handle.')],
 ['Independent artists and bands.', 'DJs and producers.', 'Managers acting for artists.'])

u('instagram-username-matching-your-domain-name', 'Instagram Username That Matches Your Domain Name',
 'Want the Instagram username that matches your domain name?', 'Username matching your domain',
 'Want your Instagram handle to match your website domain? When a claim fits, what proof of your domain helps and what to expect.',
 'Matching your domain and handle is good for customers. If someone holds it, here is how it is assessed.',
 'If your domain is well established and someone else holds the same word as an Instagram handle, a claim can be considered. A domain alone is not a trademark, so what counts is the whole picture: how long you have traded, whether the holder is active, and whether they copy your brand. We tell you honestly if it is unlikely.',
 [('Show how long you traded', 'Domain history, invoices and archived pages.'),
  ('Check the holder', 'Empty, active or copying you?'),
  ('Do not rely on the domain alone', 'It is helpful, not decisive.')],
 [S('What helps', ul(['A domain registered before the holder opened their account.', 'A registered business or trademark with the same name.', 'The holder using your branding.', 'A long record of public use of the name.']),
    RULES),
  S('What to send', ol(['The handle you want and the matching domain.', 'Your business registration or trademark details, if any.', 'Screenshots of the holder’s profile.', 'Evidence of how long the name has been in use.']))],
 [('Is a domain enough?', 'On its own, no. It supports a claim with other evidence.'),
  ('What if the holder is a real person with the same word?', 'Active namesakes usually keep the handle.'),
  ('Can I use a variation?', 'Yes. It is often the fastest way to have a clean handle, though it is your choice.')],
 ['Startups and online businesses.', 'Agencies buying a brand domain.', 'Freelancers with a personal domain.'])

u('instagram-username-claim-singapore', 'Instagram Username Claim in Singapore',
 'Want an Instagram username in Singapore?', 'Username claim in Singapore',
 'Singapore business or creator whose name is held on Instagram by someone else? What ACRA and IPOS records add and how a claim is assessed.',
 'Singapore sole proprietors and startups often register a business first and find the handle taken later.',
 'Many Singapore businesses register with ACRA first and look for the Instagram handle afterwards. If someone else holds it, the strength of a claim depends on your ACRA profile, any IPOS trademark, and what the holder does with the account. Send the handle and your business details, and we tell you what is realistic.',
 [('Start with your ACRA profile', 'The registered name and date show how long the name has been yours.'),
  ('IPOS filings help', 'A registered or pending mark carries more weight than a trading name.'),
  ('Look at the holder', 'An empty handle and a copycat are treated differently.')],
 [S('Records that matter here', ul(['The ACRA business profile with registration date.', 'An IPOS trademark filing, if you have one.', 'Invoices or listings that show the name in use.', 'The date the holder opened the account.']), RULES),
  S('How to start', ol(['Write down the handle you want and the one you use now.', 'Collect your ACRA profile and any IPOS details.', 'Screenshot the holder’s profile and latest post.', 'Send the three items and a line about why the name is yours.']))],
 [('Does a sole proprietorship count?', 'A registered sole proprietorship is evidence of the name. A trademark adds more.'),
  ('Do you only work with Singapore clients?', 'No. Unbanz works with clients worldwide.'),
  ('What if the holder is a real shop with a similar name?', 'An active, genuine owner usually keeps the handle.')],
 ['Sole proprietors and small companies.', 'Consultants and creators.', 'Agencies serving Singapore clients.'], area='Singapore')

u('instagram-username-claim-netherlands', 'Instagram Username Claim in the Netherlands',
 'Want an Instagram username in the Netherlands?', 'Username claim in the Netherlands',
 'Dutch business or webshop whose name is used on Instagram by someone else? What a KvK entry and a Benelux mark add, and what to send.',
 'A Dutch trade name is not always the same as the name on the Instagram handle you want. Here is how that plays out.',
 'In the Netherlands the name on your KvK entry and the name customers know often differ, and a third party may hold the handle. A KvK extract shows the trade name and its start date, and a Benelux trademark covers three countries. Send these with the holder’s profile and we say if a claim is realistic.',
 [('Match the trade name', 'The KvK trade name should be the word in the handle you want.'),
  ('A Benelux mark covers three countries', 'It supports a brand report more than a trade name alone.'),
  ('Note the holder’s language', 'A Dutch-language account selling the same thing looks different to a hobby page.')],
 [S('What the Dutch records show', ul(['The KvK extract with the trade name and start date.', 'A BOIP trademark registration, if filed.', 'Webshop pages or invoices carrying the name.', 'Whether the holder sells under your name.']), RULES),
  S('Sending your details', ol(['The handle you want and the one you run today.', 'Your KvK extract and any trademark number.', 'A screenshot of the holder’s profile.', 'A short line explaining the link to your name.']))],
 [('Can I write in Dutch?', 'Yes. You can write in Dutch or English.'),
  ('Is a KvK number enough?', 'It supports a claim but is not decisive on its own.'),
  ('What if the holder is another Dutch shop?', 'An active shop with its own claim to the word usually keeps it.')],
 ['Webshops and retailers.', 'Freelancers with a trade name.', 'Agencies serving Dutch clients.'], area='Netherlands')

u('instagram-username-claim-france', 'Instagram Username Claim in France',
 'Want an Instagram username in France?', 'Username claim in France',
 'French independent or boutique whose name is held on Instagram by someone else? What a SIREN record and an INPI mark add and what to send.',
 'In France the company name and the name on the shop front are often not the same. That matters for a handle.',
 'French independents often trade under a name that differs from the legal company name. The handle you want may be held by an old account or a copycat. A SIREN record shows the registered business, and an INPI filing protects the name. Send them with a screenshot of the holder’s profile and we say whether a claim is realistic.',
 [('Know your nom commercial', 'The name customers see should appear on a record you can show.'),
  ('An INPI filing helps', 'A registered mark carries more weight than a business name.'),
  ('Check the holder', 'Abandoned accounts and copycats are handled differently.')],
 [S('What French records show', ul(['A SIREN record with the activity start date.', 'An INPI trademark registration or filing.', 'A shop sign, menu or invoice with the name.', 'Whether the holder reuses your logo.']), RULES),
  S('Before you contact us', ol(['Note the handle you want and your current one.', 'Gather the SIREN record and any INPI number.', 'Screenshot the holder’s profile.', 'Add one line on why the name is yours.']))],
 [('Can I write in French?', 'Yes. You can write in French or English.'),
  ('Does a micro-entreprise count?', 'It is evidence of the name. A trademark adds more.'),
  ('What if the holder is a namesake abroad?', 'An active owner with a genuine claim usually keeps it.')],
 ['Boutiques, restaurants and local brands.', 'Independent professionals.', 'Agencies serving French clients.'], area='France')
